import {applyDpsBuffs} from './dps-buffs.js?v=class-power-1';
const buffResponse=await fetch('data/dps-buffs.json?v=linear-2');
const buffRules=buffResponse.ok?await buffResponse.json():{fortune:{},heroGroups:[]};
import {itemTooltip} from './item-tooltip.js?v=compact-2';
import {captureRotation,restoreRotation,saveNamedPreset} from './dps-presets.js';
import {calculate,classes,fresh,worlds,slots,resolveItem,itemTier} from './model.js?v=class-power-1';
import {referenceEnemies} from './combat-tips.js';
import {simulateRotation,targeting} from './dps.js?v=class-power-1';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>n==null?'—':Number(n.toFixed(2)).toLocaleString('ru-RU');
const storageKey='ligmarbd.dps.v1';let config=null,alt=false,tipData=null;
function tooltip(){const el=document.getElementById('dps-tooltip');if(!el||!tipData)return;el.hidden=false;if(tipData.kind==='item'){el.innerHTML=tipData.html;return;}if(tipData.kind==='skill'){el.innerHTML=`<strong>${escape(tipData.name)} · ${tipData.level||'—'} ур.</strong><p>${escape(tipData.description)}</p>`;return;}const {breakdown,cycle}=tipData;el.innerHTML=`<strong>${alt?'Урон по целям':'ДПС по целям'}</strong>${breakdown.length?breakdown.map(b=>`<p>${escape(b.name)}: ${alt?`${number(b.after)} после брони (${number(b.before)} до брони − ${number(b.removed)} срезано)`:`${number(cycle>0?b.after/cycle:null)}`}</p>`).join(''):'<p>Урона нет.</p>'}<small>${alt?'Суммарный урон применения с учётом выбранного режима.':`Урон после брони / (длительность действия + откат): ${number(cycle)} с. Alt — суммарный урон.`}</small>`}
window.addEventListener('keydown',e=>{if(e.key==='Alt'){alt=true;document.documentElement.classList.add('dps-alt');tooltip()}});
window.addEventListener('keyup',e=>{if(e.key==='Alt'){alt=false;document.documentElement.classList.remove('dps-alt');tooltip()}});
window.addEventListener('blur',()=>{alt=false;document.documentElement.classList.remove('dps-alt');const t=document.getElementById('dps-tooltip');if(t)t.hidden=true;tipData=null});
function paperdoll(build,items){
 const cls=classes[build.classId];
 const slot=key=>{const equipped=build.equipment[key],item=equipped&&resolveItem(items,equipped.id,equipped.quality),name=slots[key]+': '+(item?item.name.ru:'пусто'),best=Math.max(0,...(equipped?.props||[]).map(p=>p.percent));return `<div class="gear-slot ${escape(equipped?.quality||'empty')}" ${item?`data-item-tip="${key}" tabindex="0" aria-describedby="dps-tooltip"`:''} role="img" aria-label="${escape(name)}">${item?`<img src="assets/${escape(item.image_path)}" alt=""><span class="tier ${best>=150?'tier-ancient':best>=100?'tier-perfect':''}">${({4:'IV',6:'VI',8:'VIII'})[itemTier(item,equipped.quality)]||''}</span>${equipped.enchant?`<b>+${equipped.enchant}</b>`:''}`:`<span class="dps-empty-slot">${escape(slots[key])}</span>`}</div>`};
 return `<div class="dps-paperdoll" aria-label="Экипировка персонажа">${cls.portrait?`<img class="dps-portrait" src="assets/images/items/skins/${cls.portrait}.webp" alt="${escape(cls.name)}">`:`<div class="dps-class-emblem"><img src="assets/icons/${build.classId}.svg" alt="${escape(cls.name)}"></div>`}<div class="dps-gear-column">${['weapon','shoulders','neck','waist','finger'].map(slot).join('')}</div><div class="dps-gear-column dps-gear-right">${['head','chest','hands','legs','feet'].map(slot).join('')}</div></div>`;
}
export function mountDps(root,{builds,items,catalog}){
 const defaults=()=>{const enemy=referenceEnemies(items).archer;return {version:1,selectedId:builds[0]?.id??null,mode:'expected',allies:1,allVisible:true,targets:[{id:'target-1',name:'Цель 1',range:'melee',visible:true,level:55,defense:enemy.defense,resistance:enemy.resistance,evasion:enemy.evasion}],plans:{}}};
 if(!config){try{const saved=JSON.parse(localStorage.getItem(storageKey));config=saved?.version===1&&Array.isArray(saved.targets)&&saved.targets.length>0&&saved.targets.length<=8&&saved.targets.every(t=>t&&typeof t.id==='string'&&typeof t.name==='string'&&['level','defense','resistance','evasion'].every(k=>Number.isFinite(t[k])&&t[k]>=0)&&t.level>=1)&&saved.plans&&typeof saved.plans==='object'&&!Array.isArray(saved.plans)&&Object.values(saved.plans).every(p=>Array.isArray(p)&&p.length<=200&&p.every(s=>s&&['skill','wait','run'].includes(s.kind)))&&['expected','normal'].includes(saved.mode)&&Number.isInteger(saved.allies)&&saved.allies>=1&&saved.allies<=20?saved:defaults()}catch{config=defaults()}}
 if(!builds.some(b=>b.id===config.selectedId))config.selectedId=(builds.find(b=>b.build.world===config.world)||builds[0])?.id??null;
 config.allVisible=config.allVisible!==false;
 for(const t of config.targets){delete t.speed;t.range=t.range==='ranged'?'ranged':'melee';t.enemyTarget=['hero','ally','none'].includes(t.enemyTarget)?t.enemyTarget:t.visible===false?'none':'hero';}
 config.world=worlds[config.world]?config.world:(builds.find(b=>b.id===config.selectedId)?.build.world||'ostrog');
 config.enemyPresets=Array.isArray(config.enemyPresets)?config.enemyPresets:[];
 config.rotationPresets=Array.isArray(config.rotationPresets)?config.rotationPresets:[];
 config.buffSelections=config.buffSelections&&typeof config.buffSelections==='object'?config.buffSelections:{};
 let presetMessage='';
 let saveError=false;
 const save=()=>{try{localStorage.setItem(storageKey,JSON.stringify(config));saveError=false}catch{saveError=true}};
 function render(){
  const worldBuilds=builds.filter(b=>b.build.world===config.world);
  const selected=worldBuilds.find(b=>b.id===config.selectedId)||worldBuilds[0],sourceBuild=selected?.build||fresh();
  if(!selected){root.innerHTML='<section class="panel">Нет персонажей выбранного мира.</section>';return;}
  config.selectedId=selected.id;
  const buffKey=selected.id+':'+sourceBuild.world,selection=config.buffSelections[buffKey]??={heroes:'none',prosperity:0,casino:0};
  const buffResult=applyDpsBuffs(sourceBuild,selection,builds,buffRules),build=buffResult.build;
  const planKey=selected.id+':'+build.classId,steps=config.plans[planKey]??=[];
  const skills=(catalog[build.classId]||[]).filter(s=>s.type!=='passive');
  const result=simulateRotation(build,items,catalog,steps,config.targets,{mode:config.mode,learnedOnly:selected.learnedOnly,allies:config.allies,allVisible:config.allVisible});
  if(buffResult.warnings.some(w=>!w.includes('экстраполяция'))){result.complete=false;result.dps=result.tailDps=null;}
  result.diagnostics.push(...buffResult.warnings);
  const hero=calculate(build,items),skillOptions=(id)=>'<option value="">Не выбрано</option>'+skills.map(s=>{const level=s.autoAttack?1:build.skills?.[s.id]||0;return `<option value="${s.id}" ${s.id===id?'selected':''} ${selected.learnedOnly&&!level?'disabled':''}>${escape(s.name)}${selected.learnedOnly?(level?' · '+level+' ур.':' · Не изучено'):''}</option>`}).join('');
  const choice=(value,list)=>list.map(([v,label])=>`<option value="${escape(v)}" ${v===value?'selected':''}>${escape(label)}</option>`).join('');
  const characterOptions=Object.entries(classes).map(([id,cls])=>{const entries=worldBuilds.filter(b=>b.build.classId===id);return entries.length?`<optgroup label="${escape(cls.name)}">${choice(selected.id,entries.map(b=>[b.id,b.label]))}</optgroup>`:''}).join('');
  const presetControls=(kind,title,list)=>`<div class="dps-preset"><label>${title}<select id="dps-${kind}-preset"><option value="">Выберите пресет</option>${choice('',list.map(p=>[p.id,p.name]))}</select></label><button id="dps-${kind}-apply" class="secondary" disabled>Применить</button><label>Название<input id="dps-${kind}-name" maxlength="60" placeholder="Название пресета"></label><button id="dps-${kind}-save" class="secondary">Сохранить</button></div>`;
  const enemyPresets=config.enemyPresets.filter(p=>p.world===config.world),rotationPresets=config.rotationPresets.filter(p=>p.world===config.world&&p.classId===build.classId);
  const buffNames={experience:'Опыт',silver:'Серебро',dropChance:'Шанс предметов',defense:'Защита',resistance:'Сопротивление',attack:'Атака',physicalAttack:'Физ. атака',magicAttack:'Маг. атака',magicExtra:'Доп. маг. урон',hp:'Здоровье',evasion:'Уклонение',movementSpeed:'Скорость движения',haste:'Скорость атаки и активации',healthRegen:'Регенерация HP',manaRegen:'Регенерация маны'};
  const bonusesText=bonuses=>Object.entries(bonuses).map(([k,v])=>`${buffNames[k]||k}: +${v}${k.endsWith('Regen')?'/с':'%'}`).join(' · ');
  const buffRow=(key,label,choices)=>`<div class="dps-buff-row"><span>${label}</span><div role="group" aria-label="${label}">${choices.map(([value,title])=>`<button class="secondary" data-buff-choice="${key}" data-value="${value}" aria-pressed="${String(selection[key])===String(value)}" title="${key==='heroes'?'':escape(bonusesText(buffRules.fortune[value]||{}))}">${title}</button>`).join('')}</div></div>`;
  const buffPanel=`<section class="panel dps-buffs"><h2>Баффы</h2>${buffRow('heroes','Баффы героев',[['none','Без баффов'],['house','Домик'],['fountain','Фонтан']])}${buffRow('prosperity','Процветание',[[0,'Нет'],[1,'1 лвл'],[2,'2 лвл'],[3,'3 лвл']])}${buffRow('casino','Казик',[[0,'Нет'],[1,'1 лвл'],[2,'2 лвл'],[3,'3 лвл']])}<small>Три группы складываются. Баффы из настроек персонажа сохраняются.</small>${buffResult.details.length?`<details id="dps-active-buffs" ${config.activeBuffsOpen?'open':''}><summary>Активные бонусы</summary>${buffResult.details.map(d=>`<p><strong>${escape(d.name)} · ${d.level} ур.${d.estimated?' ≈':''}</strong><br>${escape(bonusesText(d.bonuses))}</p>`).join('')}</details>`:''}</section>`;
  root.innerHTML=`<div class="page-title"><div><span class="eyebrow">ПЛАНИРОВАНИЕ БОЯ</span><h1>ДПС-трекер</h1></div><span class="edition">${saveError?'Не удалось сохранить':'Ротация сохраняется локально'}</span></div><section class="panel dps-settings"><label>Мир<select id="dps-world">${choice(config.world,Object.entries(worlds).map(([id,w])=>[id,w.name]))}</select></label><label>Персонаж<select id="dps-character">${characterOptions}</select></label><label>Режим урона<select id="dps-mode">${choice(config.mode,[['expected','Средний: криты и промахи'],['normal','Обычные попадания: без критов']])}</select></label><label>Союзников, включая героя<input id="dps-allies" type="number" min="1" max="20" value="${config.allies}"></label><div class="dps-presets">${presetControls('enemies','Пресет врагов',enemyPresets)}${presetControls('rotation','Пресет порядка умений',rotationPresets)}<small>То же название — обновить пресет. ${escape(presetMessage)}</small></div></section><section class="dps-combatants"><div class="dps-hero-column"><article class="panel dps-hero"><div class="dps-hero-details"><span class="eyebrow">ПЕРСОНАЖ</span><h2>${escape(build.name)}</h2><p>${classes[build.classId].name} · ${build.level} ур. · ${build.world==='zion'?'Зион':'Острог'}</p><div class="skill-facts"><span>Урон ${number(hero.attack[0])}–${number(hero.attack[1])}</span><span>ВА ${hero.activation}%</span><span>Крит ${hero.crit}%</span><span title="${escape(['mage','priest'].includes(build.classId)?'У класса нет автоатаки':`1000 / ((${number(hero.attackIntervalBase)} − ${number(hero.attackIntervalReduction)}) × ${number(build.dpsExternal?.speedMultiplier??1)}) мс`)}">Ударов/с ${hero.attacksPerSecond===null?'—':number(hero.attacksPerSecond)}</span></div><small>${selected.learnedOnly?'Доступны только изученные умения.':'Уровни умений задаются в ротации.'}</small></div>${paperdoll(build,items)}</article>${buffPanel}</div><article class="panel dps-targets"><div class="preset-heading"><h2>Цели</h2><button id="dps-add-target" class="secondary" ${config.targets.length>=8?'disabled':''}>＋ Цель</button></div><label class="dps-visibility"><input id="dps-all-visible" type="checkbox" ${config.allVisible?'checked':''}>Все враги видимы</label>${config.targets.map((t,i)=>`<section class="dps-target" aria-label="Цель ${i+1}"><div class="dps-target-heading"><span>Враг ${i+1}</span><button data-remove-target="${i}" aria-label="Удалить цель ${i+1}" title="Удалить цель" ${config.targets.length===1?'disabled':''}>×</button></div><div class="dps-target-identity"><label>Имя<input data-target="${i}" data-field="name" value="${escape(t.name)}" maxlength="40"></label><label>Уровень<input data-target="${i}" data-field="level" type="number" min="1" max="100" value="${t.level}"></label></div><fieldset class="dps-target-defense"><legend>Защитные параметры</legend><div><label>Защита<input data-target="${i}" data-field="defense" type="number" min="0" max="1000000" value="${t.defense}"></label><label>Сопротивление<input data-target="${i}" data-field="resistance" type="number" min="0" max="1000000" value="${t.resistance}"></label><label>Уклонение<input data-target="${i}" data-field="evasion" type="number" min="0" max="1000000" value="${t.evasion}"></label></div></fieldset><fieldset class="dps-target-behavior"><legend>Поведение в бою</legend><div><label>Дальность<select data-target="${i}" data-field="range">${choice(t.range,[['melee','Ближний'],['ranged','Дальний']])}</select></label><label>Кого атакует в начале<select data-target="${i}" data-field="enemyTarget">${choice(t.enemyTarget,[['hero','Герой'],['ally','Союзник'],['none','Нет цели']])}</select></label></div></fieldset></section>`).join('')}<details class="dps-target-notes"><summary>Как считаются видимость и поиск цели</summary><p class="hint">Поиск цели: (0,8 с у дальника / 1,5 с у ближника) ÷ его скорость. По умолчанию скорость 1. Замедления ротации учитываются автоматически: скорость = 1 − замедление / 100. Новое замедление заменяет старое. Скорость пока фиксируется в момент начала поиска; после потери цели поиск начинается по окончании контроля. В модели враг после поиска выбирает героя. Начальные статы — хай тир лучника 55 уровня; броня постоянна. В формуле снижения используется уровень атакующего героя.</p></details></article></section><section class="panel dps-rotation"><div class="preset-heading"><h2>Порядок умений</h2><div class="actions"><button id="dps-add" class="secondary" ${steps.length>=200?'disabled':''}>＋ Умение</button><button id="dps-run" class="secondary" ${steps.length>=200?'disabled':''}>＋ Бег</button><button id="dps-wait" class="secondary" ${steps.length>=200?'disabled':''}>＋ Пауза</button></div></div>${selected.learnedOnly&&!skills.some(s=>s.autoAttack||(build.skills?.[s.id]||0)>0)?'<p class="hint">У персонажа нет изученных активных умений. Выберите их в разделе «Мои персонажи».</p>':''}<p class="hint">Строки выполняются сверху вниз. Откат начинается в конце каста. Ошибки не исправляются автоматическим ожиданием. ДПС строки = суммарный урон / (длительность действия + откат). Alt — суммарный урон и исходное время каста.</p><div class="dps-table-scroll"><table class="dps-table"><thead><tr><th>Время</th><th>Умение</th><th>Таргетинг</th><th>Каст</th><th>Откат</th><th><span class="dps-actual">ДПС</span><span class="dps-original">Урон Σ</span></th><th>Эффекты</th><th>Порядок</th></tr></thead><tbody>${steps.map((step,i)=>{
   const row=result.rows[i],skill=row.skill,rank=row.rank,kind=skill?targeting(skill,rank):null;
   const cycle=row.cast==null?null:row.cast+(row.cooldown??0),dps=row.total!==null&&cycle>0?row.total/cycle:null;
   return `<tr class="${row.errors.length?'dps-invalid':row.warnings.length?'dps-warning':''}"><td><span title="Начало">${number(row.start)} с</span><small title="Окончание">→ ${number(row.end)} с</small></td><td>${['wait','run'].includes(step.kind)?`<label>${step.kind==='run'?'Бег':'Пауза'}, с<input data-step="${i}" data-step-field="seconds" type="number" min="0" max="3600" step="0.1" value="${step.seconds??0.3}"></label>`:`<div class="dps-skill-choice"><select data-step="${i}" data-step-field="skillId" aria-label="Умение ${i+1}">${skillOptions(step.skillId)}</select><button type="button" class="dps-skill-info" data-skill-info="${i}" aria-label="Описание умения ${i+1}" aria-describedby="dps-tooltip" ${skill?'':'disabled'}>ⓘ</button></div>${selected.learnedOnly?'':`<label class="dps-rank">Уровень<select data-step="${i}" data-step-field="level" aria-label="Уровень умения ${i+1}">${Array.from({length:skill?.maxLevel||10},(_,n)=>`<option value="${n+1}" ${n+1===Number(step.level)?'selected':''}>${n+1}</option>`).join('')}</select></label>`}${skill?.autoAttack?`<label class="dps-rank">Ударов<input data-step="${i}" data-step-field="hits" aria-label="Число ударов ${i+1}" type="number" min="1" max="1000" step="1" value="${step.hits??1}"></label>`:''}${skill?.channelIntervalMs?`<label class="dps-rank">Залпов в стойке<input data-step="${i}" data-step-field="volleys" aria-label="Залпов в стойке ${i+1}" type="number" min="0" max="999" step="1" value="${step.volleys??0}"></label><small>После первого залпа · интервал 3 с</small>`:''}`}</td><td>${['attack','curse'].includes(skill?.type)?`<select data-step="${i}" data-step-field="targetId" aria-label="Цель умения ${i+1}">${choice(step.targetId??config.targets[0].id,[...(kind==='single'?[]:[['','Без выбранной цели']]),...config.targets.map(t=>[t.id,t.name])])}</select>`:''}<small>${escape(row.targetLabel||'—')}</small></td><td><span class="dps-actual">${number(row.cast)}</span><span class="dps-original">${number(row.originalCast)}</span> с</td><td>${number(row.cooldown)} с</td><td><span class="dps-damage" ${row.total!==null?`tabindex="0" data-damage="${i}" aria-describedby="dps-tooltip"`:""}><span class="dps-actual">${number(dps)}</span><span class="dps-original">${number(row.total)}</span>${row.total!==null?' ⓘ':''}</span></td><td><span title="${escape(row.effects.map(e=>e.label).join('\n'))}">${row.effects.length?[...new Set(row.effects.map(e=>number(e.seconds)+' с'))].join(' / '):'—'}</span></td><td><div class="dps-order"><button data-move="${i}" data-direction="-1" aria-label="Шаг ${i+1} вверх" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-direction="1" aria-label="Шаг ${i+1} вниз" ${i===steps.length-1?'disabled':''}>↓</button><button data-remove-step="${i}" aria-label="Удалить шаг ${i+1}">×</button></div></td></tr>${row.errors.length||row.warnings.length?`<tr class="dps-messages"><td colspan="8">${row.errors.map(m=>`<p class="dps-error">Ошибка: ${escape(m)}</p>`).join('')}${row.warnings.map(m=>`<p class="skill-warning">Предупреждение: ${escape(m)}</p>`).join('')}</td></tr>`:''}`;
  }).join('')}</tbody></table></div>${!steps.length?'<div class="dps-empty">Добавьте первое умение — здесь появятся время и урон каждого применения.</div>':''}</section><section class="panel dps-summary"><h2>${result.complete?'Результат ротации':'Предварительный расчёт'}</h2><div class="dps-numbers"><div><span>До конца кастов</span><strong>${number(result.during)}</strong><small>${number(result.end)} с</small></div><div><span>С учётом хвоста DOT</span><strong>${number(result.total)}</strong><small>до ${number(result.tailEnd)} с</small></div><div><span>DPS до конца кастов</span><strong>${number(result.dps)}</strong></div><div><span>DPS с хвостом DOT</span><strong>${number(result.tailDps)}</strong></div></div>${!result.complete?'<p class="skill-warning">Есть ошибки или нерассчитанные механики. Показана только известная часть урона; итоговый DPS не определён.</p>':''}${result.diagnostics.map(w=>`<p class="skill-warning">${escape(w)}</p>`).join('')}${result.passiveApplied?`<p class="hint">${escape(result.passiveApplied)} учтена вместо вручную заданной пассивки атаки.</p>`:''}</section><details class="panel calculation-notes"><summary>Допущения расчёта</summary><p>Урон — среднее границ диапазона. В среднем режиме прямые удары учитывают крит (база 200%) и меткость; умения мага и жреца обычную проверку попадания не проходят. Тики DOT не критуют и не проверяют уклонение повторно.</p><p>DOT тикает сразу при наложении и далее раз в секунду. Повторное успешное наложение заменяет остаток. В среднем режиме учтена вероятность промаха нового наложения. При совпадении времени сначала происходит обновление DOT, затем тик. Σ в строке — фактически оставшийся урон этого применения, включая хвост DOT.</p><p>«Ближние» поражает всех видимых ближников и текущую выбранную цель, даже дальнюю. Враг виден, если выбрал героя/союзника либо выбран героем; общая галочка делает видимыми всех. Видимые дальники подходят во время связок, стана или агра. «Группа» поражает все цели независимо от дальности и видимости. Проверка — в конце каста. Случайный контроль не считается гарантированным; зависимый от него DPS помечается как неопределённый. Уровень цели не заменяет уровень атакующего в формуле брони.</p><p>Автоатака занимает число ударов × интервал оружия с учётом ПМА; удар в конце каждого интервала. Первый залп обстрела — после каста с ВА, дополнительные — каждые 3 с. Откат обстрела пока считается от выхода из стойки после последнего залпа. Бег: откат 3 с после завершения. Обездвиженные сном, станом или связками враги теряют героя из цели. Во время бега действует отдельная проверка промаха: 25% для дальних умений, 50% для дальних атак и ближних умений, 75% для ближних атак. Входящие атаки пока не моделируются. Нет входящих ударов, проверки запаса маны, перемещения и синхронизации уровня умений по миру. Неопределённые механики отмечаются отдельно. Время строки с ошибкой — планируемое, не успешный каст. Разные эффекты по умолчанию сосуществуют; предупреждения выводятся для повторов, замедлений и явно несовместимых умений.</p></details>`;
  let tip=document.getElementById('dps-tooltip');if(!tip){tip=document.createElement('div');tip.id='dps-tooltip';tip.className='dps-tooltip';tip.setAttribute('role','tooltip');document.body.append(tip)}tip.hidden=true;tipData=null;
  const activeBuffs=root.querySelector('#dps-active-buffs');
  if(activeBuffs)activeBuffs.ontoggle=()=>{if(!activeBuffs.isConnected)return;config.activeBuffsOpen=activeBuffs.open;save()};
  root.querySelectorAll('[data-buff-choice]').forEach(el=>el.onclick=()=>{if(activeBuffs)config.activeBuffsOpen=activeBuffs.open;selection[el.dataset.buffChoice]=el.dataset.buffChoice==='heroes'?el.dataset.value:Number(el.dataset.value);save();render()});
  root.querySelector('#dps-world').onchange=e=>{config.world=e.target.value;presetMessage='';save();render()};
  for(const kind of ['enemies','rotation']){
   const list=kind==='enemies'?enemyPresets:rotationPresets;
   const select=root.querySelector(`#dps-${kind}-preset`),name=root.querySelector(`#dps-${kind}-name`),apply=root.querySelector(`#dps-${kind}-apply`);
   select.onchange=()=>{const preset=list.find(p=>p.id===select.value);apply.disabled=!preset;if(preset)name.value=preset.name;};
   apply.onclick=()=>{const preset=list.find(p=>p.id===select.value);if(!preset)return;
    if(kind==='enemies'){const rotation=captureRotation(steps,config.targets);config.targets=structuredClone(preset.targets);config.allVisible=preset.allVisible!==false;config.plans[planKey]=restoreRotation(rotation,config.targets);}
    else config.plans[planKey]=restoreRotation(preset.steps,config.targets);
    presetMessage=`Применён пресет «${preset.name}»`;save();render();};
   root.querySelector(`#dps-${kind}-save`).onclick=()=>{const title=name.value.trim();if(!title){name.setCustomValidity('Введите название пресета');name.reportValidity();return;}name.setCustomValidity('');
    const common={id:crypto.randomUUID(),name:title,world:config.world};
    if(kind==='enemies')config.enemyPresets=saveNamedPreset(config.enemyPresets,{...common,targets:config.targets,allVisible:config.allVisible});
    else config.rotationPresets=saveNamedPreset(config.rotationPresets,{...common,classId:build.classId,steps:captureRotation(steps,config.targets)});
    presetMessage=`Сохранён пресет «${title}»`;save();render();};
   name.oninput=()=>name.setCustomValidity('');
  }
  root.querySelector('#dps-character').onchange=e=>{config.selectedId=e.target.value;save();render()};
  root.querySelector('#dps-all-visible').onchange=e=>{config.allVisible=e.target.checked;save();render()};
  root.querySelector('#dps-mode').onchange=e=>{config.mode=e.target.value;save();render()};
  root.querySelector('#dps-allies').onchange=e=>{config.allies=Math.max(1,Math.min(20,Math.floor(+e.target.value)||1));save();render()};
  root.querySelector('#dps-add').onclick=()=>{steps.push({kind:'skill',skillId:'',level:1,targetId:config.targets[0].id,targetCount:config.targets.length});save();render()};
  root.querySelector('#dps-run').onclick=()=>{steps.push({kind:'run',seconds:0.3});save();render()};
  root.querySelector('#dps-wait').onclick=()=>{steps.push({kind:'wait',seconds:1});save();render()};
  root.querySelector('#dps-add-target').onclick=()=>{config.targets.push({...config.targets[0],id:crypto.randomUUID(),name:'Цель '+(config.targets.length+1)});save();render()};
  root.querySelectorAll('[data-target]').forEach(el=>el.onchange=()=>{const t=config.targets[+el.dataset.target],k=el.dataset.field;t[k]=k==='visible'?el.checked:['range','enemyTarget'].includes(k)?el.value:k==='name'?(el.value.trim()||'Цель'):Math.max(k==='level'?1:0,Math.min(k==='level'?100:1000000,+el.value||0));save();render()});
  root.querySelectorAll('[data-remove-target]').forEach(el=>el.onclick=()=>{config.targets.splice(+el.dataset.removeTarget,1);save();render()});
  root.querySelectorAll('[data-step]').forEach(el=>el.onchange=()=>{const step=steps[+el.dataset.step],k=el.dataset.stepField;step[k]=['skillId','targetId'].includes(k)?el.value:+el.value;if(k==='skillId'){const s=skills.find(s=>s.id===el.value);step.level=s?(selected.learnedOnly?(s.autoAttack?1:build.skills?.[s.id]||0):Math.min(...Object.keys(s.ranks).map(Number))):1}save();render()});
  root.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>{const i=+el.dataset.move,j=i+(+el.dataset.direction);[steps[i],steps[j]]=[steps[j],steps[i]];save();render()});
  root.querySelectorAll('[data-remove-step]').forEach(el=>el.onclick=()=>{steps.splice(+el.dataset.removeStep,1);save();render()});
  root.querySelectorAll('[data-item-tip]').forEach(el=>{
   el.onmouseenter=el.onfocus=()=>{const equipped=build.equipment[el.dataset.itemTip],item=equipped&&resolveItem(items,equipped.id,equipped.quality);if(!item)return;tipData={kind:'item',html:itemTooltip(item,equipped)};tooltip()};
   el.onmouseleave=el.onblur=()=>{tip.hidden=true;tipData=null};
  });
  root.querySelectorAll('[data-skill-info]').forEach(el=>{
   el.onmouseenter=el.onfocus=()=>{const row=result.rows[+el.dataset.skillInfo],skill=row.skill;if(!skill)return;tipData={kind:'skill',name:skill.name,level:row.level,description:skill.ranks[row.level]?.description||'Нет описания для выбранного уровня умения.'};tooltip()};
   el.onmouseleave=el.onblur=()=>{tip.hidden=true;tipData=null};
  });
  root.querySelectorAll('[data-damage]').forEach(el=>{el.onmouseenter=el.onfocus=()=>{const row=result.rows[+el.dataset.damage];tipData={breakdown:row.breakdown,cycle:row.cast==null?null:row.cast+(row.cooldown??0)};tooltip()};el.onmouseleave=el.onblur=()=>{tip.hidden=true;tipData=null}});
 }
 render();
}
